return {
  CAREER = "SI-DT系列是火神重工专为破坏性测试设计的人形。考虑到破坏性测试中必然出现的损害，SI-DT的机体设计同时具备成本低廉、结构简易、部件易于更换等特性，在遭受极严重损害的情况下仍能确保核心组件的安全并继续进行数据收集。在投入使用后，SI-DT不仅有效减少了破坏性测试的成本与风险，还进一步提高了数据收集效率，为材料科学以及人形技术的发展做出了杰出贡献。\n\n但长期的高强度实验也使得SI-DT的损耗率居高不下。随着成本更加低廉的替代品的出现，SI-DT很快淡出了市场。在火神重工的推荐下，现存唯一完好的SI-DT后期型个体“赫瓦可”被送往了42Lab，参与心智云图计划。",
  INFOSTORY1 = "将材料科学应用到实践领域的过程中，材料寿命，结构和强度等指标可谓至关重要。人类不断地追求制造出强度更高、重量更轻、结构更巧妙的材料，然后用这些材料来制造出更先进的物件改变世界。而通过破坏性实验来测试材料的强度和结构，是材料科学研究过程中必不可缺的一环，尽管这么做通常会带来附带破坏与沉没成本，在某些情况下还会对实验操作者的身体、精神健康造成威胁。出于以上原因，许多科研机构和企业都开始着手研发能够尽可能降低实验成本、减少试验风险的方案，而火神重工给出的答案便是SI-DT系列人形。\n\n“用人形来替代人类执行高风险工作”是火神重工研发人形的一贯主旨，尽管这一主旨也受到了越来越多的争议，但无可否认，这样确实行之有效。SI-DT不仅能够代替人类承担枯燥而又重复的破坏内容，同时也担任材料的破坏性测试平台。SI-DT的机体被设计为结构简单、易于替换且低成本，但强度则尽可能地高，在遭受极严重破坏的情况下仍能进行快速维修，甚至在极端情况下可以兼容老式人形的零件。SI-DT的绝大部分成本都用于增强数据核心防护以及反馈系统，因而其感官系统的设计也在人形中较为特殊。得益于这些设计，SI-DT可以更为直观的将身体每一处材料的变化记录并确定其极限。",
  INFOSTORY2 = "“赫瓦可”这一名字究竟从何而来？就连她自己也只能摇头并表示不知情，或者回你一句“随便起的啦”。但只从词面意思上看反而颇好理解——“毁坏、浩劫”，正如她在一次次实验中用各种各样的设备所做的。\n\n还有一个未经证实，听上去荒诞不经但颇有些趣味的说法，“Havoc”这个名字来自一个千禧年时期发售的射击游戏的主角，一个身材高大强壮、性格狂放不羁的王牌特种兵。或许是由于SI-DT普遍身材高大，因此赫瓦可才得到了这一名字。无论缘由是什么，赫瓦可似乎都对自己的这一名字颇为满意。\n\n作为后期型机体的赫瓦可于2056年年末进入火神重工下属的某研究所工作，主要负责材料实验与数据采集。据悉赫瓦可与其他SI-DT人形参与了人形素体材料研究，为人形材料学的突破贡献了自己的力量。不过，在主动或被动谈及自己的工作经历时，赫瓦可的态度并不是很情愿。\n\n“毕竟一次又一次被破坏，还是很疼很麻烦的啊，虽然没有琳德那么糟透顶……但我发誓，绝对没有别的人形愿意有这种经历吧！所以你们可以理解我想要摸鱼的心吧！”\n——赫瓦可入职面试\n\n人形骨架破坏性测试已完成。测试对象：SI-DT系列损坏人形。测试执行人：SI-DT赫瓦可。\n——《SI-DT最终实验记录》",
  INFOSTORY3 = "赫瓦可那令人印象深刻的松散性格有着多方面的成因。如先前资料所记述那般，长期恶劣且高强度的工作环境对她产生了深刻的影响，另一方面也的确有天性使然的因素，又或者说是一种广泛存在于人类和人形中的“共通”天性。\n\n大多数情况下，赫瓦可绝不会在工作上多消耗哪怕一秒，准点上班，准点下班，能摸就摸，绝不多待。甚至在工作较为空闲的时候，她会想方设法翘班——直到阿卡迪亚更新了更先进的识别系统，并将她抓了个现行为止。不过，如果承诺之后能弥补她两倍甚至三倍的假日，她倒也不介意把更多的私人时间投入到工作当中。同时，她也经常直言不讳地批评一些牺牲个人时间的工作狂行为。\n\n“连着三周加班？没问题，那之后就得放三周假！”\n即使来到了绿洲，她也依旧秉持着这一雷打不动的原则。",
  INFOSTORY4 = "众所周知，SI-DT型有着惊人的高损耗率，赫瓦可本身也经过了多次大规模维修，除心智核心和头颅外的其它部件几乎都换了一遍，并以“以改代修”的方式进行了多项增强，如将手臂的液压系统更换为更新的型号，方便轻松地操纵某些重型机械等。\n\n当心智云图计划启动的时候，赫瓦可是SI-DT里总体状况最好的那台，因此才能被火神重工和42Lab所相中，而她本身也对此表现出了相对积极的态度——这样或许就能够从高危且压抑的工作环境中脱离。她深知自己这样下去迟早有一天会和那些因结构严重衰损而退役、报废的SI-DT那样。\n\n然而即使赫瓦可擅长调节自己的心智，但是在加入云图计划之时她的状态也并不乐观。多处心智模块出现了超过1万条的报错，检修的工作人员认为她能够运转都已经堪称奇迹。归零事件之中，赫瓦可本就濒临极限的心智受外力影响而崩溃，所有模块都失去了连接。所幸她被庇护者发现得到了相应的救治。\n\n“小可在当时连语言模块都损坏了……但是她还是顽强地和我们一起做康复治疗。现在的小可已经和大多数人形没有差别了哦！”\n——德菈赛",
  INFOSTORY5 = "尽管不像“回声”小队那般需要承担庇护者主力外勤的职责，但赫瓦可因为强悍的怪力和出奇厚的耐久，也经常要执行较高风险的外勤任务，通常是中高强度的正面战。不过，在这种情况下赫瓦可通常会要求更多休假作为报酬，而他们的Boss通常也不会拒绝，毕竟虽然看上去松散怠惰，但赫瓦可总能可靠甚至漂亮地完成任务，就是偶尔需要提醒一下不要弄得太过头了。\n\n“小可那恐怖的力量……连绿洲那个有着不寻常怪力的玩具设计师都得让她三分呢。”\n——德菈赛。\n\n“站在她面前总能感受到……压迫感……虽然看到她那张不太聪明的脸之后，这种感觉很快就消散了。”\n——琳德\n\n“三倍报酬和假期当然没问题哦？不过，假如说太过火导致惹出额外的麻烦的话，那就要倒扣三倍了哦？”\n——麦戈拉决战前夕部署任务时的桑格玛"
}
